// Хлебные крошки на пути /supportinbox, /adminpanel → /dashboard (#26087e6e, план specs/admin-access.md, разделы 5–6). Только чтение.
// Запись идёт в самой странице (MutationObserver + requestAnimationFrame) с первого кадра — так ловится мелькание
// длиной 0.1–0.4 с, которое обычные expect(...) с автоповтором пропустили бы.
import * as path from 'path';
import { expect, Locator, Page } from '@playwright/test';
export { ADMIN_STATE } from '../addresses/address-helpers';

/** Сессия обычного пользователя «בדיקה», путь — от файла, чтобы не зависеть от cwd. */
export const USER_STATE = path.resolve(__dirname, '../../../auth/user.json');

/** Названия закрытых экранов, которых пользователь без прав не должен видеть ни на миг (#26087e6e). */
export const FORBIDDEN_SCREEN_NAME = /SupportInbox|AdminPanel|Support Console|Admin Panel|ממשק תמיכה|פאנל ניהול/;

export const CRUMB = {
  en: { home: 'Workspace / Home', support: 'Workspace / Support Console', admin: 'Workspace / Admin Panel' },
  he: { home: 'סביבת עבודה / בית', support: 'סביבת עבודה / ממשק תמיכה', admin: 'סביבת עבודה / פאנל ניהול' },
} as const;

export type CrumbRecord = {
  /** Сколько кадров/изменений DOM просмотрено — доказательство, что запись шла. */
  samples: number;
  /** Все разные тексты крошек по порядку. */
  crumbs: string[];
  /** Все разные document.title по порядку. */
  titles: string[];
  /** Фрагменты body.innerText, где нашлось запрещённое название (должно быть пусто). */
  bodyHits: string[];
};

/** Ставит запись крошек, заголовка вкладки и текста страницы. Вызывать до первого goto. */
export async function installCrumbRecorder(page: Page) {
  await page.addInitScript((forbiddenSource: string) => {
    const w = window as unknown as { __qaCrumbRec?: unknown };
    if (w.__qaCrumbRec) return;
    const KEY = '__qaCrumbRec';
    const FORBIDDEN = new RegExp(forbiddenSource);
    let rec = { samples: 0, crumbs: [] as string[], titles: [] as string[], bodyHits: [] as string[] };
    try {
      const saved = JSON.parse(sessionStorage.getItem(KEY) || 'null');
      if (saved && Array.isArray(saved.crumbs)) rec = saved;
    } catch { /* ignore */ }
    w.__qaCrumbRec = rec;
    let dirty = false;
    const pushNew = (arr: string[], v: string) => { if (v && arr[arr.length - 1] !== v) { arr.push(v); dirty = true; } };
    let lastBody = '';

    const sample = () => {
      rec.samples++;
      // Крошки: родитель span «Workspace» / «סביבת עבודה»
      for (const s of Array.from(document.querySelectorAll('span'))) {
        const t = (s.textContent || '').trim();
        if (t === 'Workspace' || t === 'סביבת עבודה') {
          const el = s.parentElement as HTMLElement | null;
          if (el) pushNew(rec.crumbs, (el.innerText || el.textContent || '').replace(/\s+/g, ' ').trim());
          break;
        }
      }
      pushNew(rec.titles, document.title);
      const body = document.body ? document.body.innerText || '' : '';
      if (body !== lastBody) {
        lastBody = body;
        const m = body.match(FORBIDDEN);
        if (m) {
          const i = m.index || 0;
          rec.bodyHits.push(location.pathname + ' :: ' + body.slice(Math.max(0, i - 60), i + 60).replace(/\s+/g, ' '));
          dirty = true;
        }
      }
      if (dirty) {
        dirty = false;
        try { sessionStorage.setItem(KEY, JSON.stringify(rec)); } catch { /* ignore */ }
      }
    };
    const start = () => {
      sample();
      new MutationObserver(sample).observe(document, { subtree: true, childList: true, characterData: true });
      const loop = () => { sample(); requestAnimationFrame(loop); };
      requestAnimationFrame(loop);
    };
    if (document.documentElement) start();
    else document.addEventListener('readystatechange', start, { once: true });
  }, FORBIDDEN_SCREEN_NAME.source);
}

export async function readCrumbRecord(page: Page): Promise<CrumbRecord> {
  return page.evaluate(() => {
    const r = (window as unknown as { __qaCrumbRec?: unknown }).__qaCrumbRec;
    return JSON.parse(JSON.stringify(r || { samples: 0, crumbs: [], titles: [], bodyHits: [] }));
  });
}

/** Блок хлебных крошек (родитель «Workspace» / «סביבת עבודה»). */
export function breadcrumb(page: Page): Locator {
  return page.getByText(/^(Workspace|סביבת עבודה)$/).first().locator('xpath=..');
}

/** Ждёт итоговые крошки. */
export async function expectCrumb(page: Page, text: string) {
  await expect(breadcrumb(page)).toHaveText(text, { timeout: 15_000 });
}

/**
 * Пользователь без прав: на всём пути (до и после редиректа) ни в крошках, ни в заголовке вкладки,
 * ни в тексте страницы нет названия закрытого экрана; итоговые крошки — «Workspace / Home».
 */
export async function expectNoScreenNameFlash(page: Page, homeCrumb: string) {
  const rec = await readCrumbRecord(page);
  expect(rec.samples, 'запись кадров шла').toBeGreaterThan(0);
  expect(rec.crumbs, 'итоговые крошки записаны').toContain(homeCrumb);
  expect(rec.crumbs.filter((c) => FORBIDDEN_SCREEN_NAME.test(c)), `крошки на пути: ${JSON.stringify(rec.crumbs)}`).toEqual([]);
  expect(rec.titles.filter((t) => FORBIDDEN_SCREEN_NAME.test(t)), `заголовки вкладки: ${JSON.stringify(rec.titles)}`).toEqual([]);
  expect(rec.bodyHits, 'текст страницы с названием закрытого экрана').toEqual([]);
}
